const request = $input.first().json;
const header = request.headers?.authorization ?? '';
const token = $env.ALERTMANAGER_WEBHOOK_TOKEN ?? '';

return [{ json: { authorized: token.length > 0 && header === `Bearer ${token}`, body: request.body ?? {} } }];

const body = $('Check token').first().json.body;
const project = $env.JIRA_PROJECT_KEY;

return (body.alerts ?? []).map((alert) => {
  const labels = alert.labels ?? {};
  const encoded = /[?&]g0\.expr=([^&]*)/.exec(alert.generatorURL ?? '')?.[1] ?? '';
  let expr = '';
  try {
    expr = decodeURIComponent(encoded.replace(/\+/g, ' '));
  } catch (error) {
    expr = '';
  }

  return {
    json: {
      status: alert.status,
      alertname: labels.alertname ?? 'unknown',
      severity: labels.severity ?? 'warning',
      service: labels.service ?? labels.job ?? 'unknown',
      labels,
      annotations: alert.annotations ?? {},
      startsAt: alert.startsAt,
      endsAt: alert.endsAt,
      fingerprint: alert.fingerprint,
      expr,
      jql: `project = "${project}" AND labels = "fp-${alert.fingerprint}" AND statusCategory != Done ORDER BY created DESC`,
    },
  };
});

return $input.all().map((item, index) => {
  const alert = $('Split alerts').itemMatching(index).json;
  const existing = item.json.issues?.[0]?.key ?? null;
  let action = 'skip';
  if (alert.status === 'firing' && !existing) action = 'create';
  if (alert.status === 'resolved' && existing) action = 'resolve';

  return { json: { ...alert, existing, action } };
});

const runbooks = {
  ServiceDown: 'docker compose ps and docker compose logs --tail 100 <service>; the Go services restart on their own (restart: unless-stopped); start a stopped container with docker compose up -d <service>.',
  ServiceUnhealthy: '/health answers 503 while the process runs; autoheal restarts a container that stays unhealthy; check the logs before and after the restart.',
  HighLatencyP99: 'find the slow route and a slow trace in Jaeger (database, upstream, Open-Meteo); roll back when the spike started right after a deployment of that service and nothing outside it changed.',
  HighErrorRate: 'filter the service logs by level ERROR and open a trace_id in Jaeger; usual causes are the database, RabbitMQ or an unreachable upstream; a rise right after a deployment is a reason to roll back.',
  LatencyAnomaly: 'compare routes and RPS with the previous hour and look at recent traces; prepare a rollback if it follows a deployment.',
  ReplicationLagHigh: 'check that RabbitMQ is up, the relay logs no errors and the consumers run; the relay publishes the backlog once the broker is back.',
  QueueBacklog: 'check the consumers of the queue, retry outcomes and the logs of the consuming service; scale the consumer or fix the failing handler.',
  BacklogPredicted: 'early warning: act as for ReplicationLagHigh or QueueBacklog before they fire.',
  SagaCompensationsSpike: 'look at the reason: dlq means report-service rejects events, timeout means replies do not arrive in time.',
  ExternalDependencyDown: 'Open-Meteo does not answer; reports are still created with unavailable blocks; check the network and the OPEN_METEO_* settings.',
};

const format = (value) => (Number.isFinite(value) ? Number(value.toPrecision(4)).toString() : 'n/a');

function restartFacts(alertname, restarts, autoheal) {
  const count = Number(restarts?.data?.result?.[0]?.value?.[1] ?? 0);
  const autohealLines = (autoheal?.data?.result ?? []).flatMap((stream) => stream.values.map((value) => value[1]));
  if (count > 0) {
    return autohealLines.length > 0
      ? `The process restarted ${count} time(s) since the alert started; autoheal restarted the container: ${autohealLines[0]}`
      : `The process restarted ${count} time(s) since the alert started, not by autoheal (Docker restart policy or a manual start).`;
  }
  if (alertname === 'ServiceDown') {
    return 'No restart so far: the container is not running, and autoheal only restarts running containers that are unhealthy.';
  }

  return 'No restart since the alert started.';
}

return $input.all().map((item, index) => {
  const alert = $('Decide').itemMatching(index).json;
  const metric = $('Query metric').itemMatching(index).json;
  const errors = $('Query errors').itemMatching(index).json;
  const restarts = $('Query restarts').itemMatching(index).json;

  const ownSeries = (metric?.data?.result ?? []).filter((entry) => [entry.metric.service, entry.metric.job].includes(alert.service));
  const series = ownSeries.length > 0 ? ownSeries : (metric?.data?.result ?? []).filter((entry) => !entry.metric.service && !entry.metric.job);
  const metricText = series.length === 0
    ? `No series of ${alert.service} matched the alert expression in the last 30 minutes (for ServiceDown: the target is gone).`
    : series.slice(0, 5).map((entry) => {
      const values = entry.values.map((value) => Number(value[1])).filter(Number.isFinite);
      const labels = Object.entries(entry.metric).map(([key, value]) => `${key}=${value}`).join(', ');
      return `${labels || 'value'}: last ${format(values.at(-1))}, max ${format(Math.max(...values))}`;
    }).join('\n');

  const errorLines = (errors?.data?.result ?? [])
    .flatMap((stream) => stream.values.map((value) => ({ time: value[0], line: value[1], traceId: stream.stream.trace_id ?? '' })))
    .sort((left, right) => (left.time < right.time ? 1 : -1))
    .slice(0, 5)
    .map((entry) => {
      let message = entry.line;
      try {
        const parsed = JSON.parse(entry.line);
        const request = parsed.route ? ` ${parsed.method ?? ''} ${parsed.route} ${parsed.status ?? ''}`.replace(/\s+/g, ' ') : '';
        message = `${parsed.level} ${parsed.msg}${request}${parsed.error ? `: ${parsed.error}` : ''}`;
      } catch (error) {
        message = entry.line.slice(0, 200);
      }
      return { message, traceId: entry.traceId };
    });

  const restartText = ['ServiceDown', 'ServiceUnhealthy'].includes(alert.alertname)
    ? restartFacts(alert.alertname, restarts, item.json)
    : '';
  const runbook = runbooks[alert.alertname] ?? 'see the runbook in README.md';

  const prompt = [
    `Alert: ${alert.alertname} (${alert.severity}) on ${alert.service}, firing since ${alert.startsAt}.`,
    `Summary: ${alert.annotations.summary ?? ''}`,
    `Description: ${alert.annotations.description ?? ''}`,
    `Expression: ${alert.expr}`,
    `Metric over the last 30 minutes:\n${metricText}`,
    `Recent errors and warnings:\n${errorLines.map((entry) => `- ${entry.message} (trace ${entry.traceId || 'none'})`).join('\n') || '- none'}`,
    restartText ? `Restarts: ${restartText}` : '',
    `Runbook: ${runbook}`,
  ].filter(Boolean).join('\n\n');

  return { json: { ...alert, metricText, errorLines, restartText, runbook, prompt } };
});

const priorities = { critical: 'Highest', warning: 'High', info: 'Medium' };

const paragraph = (text) => ({ type: 'paragraph', content: [{ type: 'text', text }] });
const heading = (text) => ({ type: 'heading', attrs: { level: 3 }, content: [{ type: 'text', text }] });
const link = (text, href) => ({ type: 'paragraph', content: [{ type: 'text', text, marks: [{ type: 'link', attrs: { href } }] }] });

return $input.all().map((item, index) => {
  const context = $('Build context').itemMatching(index).json;
  const fromModel = typeof item.json.output === 'string' && item.json.output.trim().length > 0;
  const analysis = fromModel
    ? item.json.output.trim()
    : `What happened: ${context.annotations.summary ?? context.alertname}.\nProbable cause: see the metric and the errors below.\nFirst steps: ${context.runbook}`;
  const jaeger = $env.JAEGER_URL;
  const traceLinks = context.errorLines.filter((entry) => entry.traceId).slice(0, 3)
    .map((entry) => link(`Trace ${entry.traceId}: ${entry.message}`, `${jaeger}/trace/${entry.traceId}`));

  const content = [
    paragraph(`Started at ${context.startsAt}. Severity ${context.severity}. Fingerprint ${context.fingerprint}.`),
    heading(fromModel ? 'Analysis (Gemini)' : 'Analysis (template, the LLM did not answer)'),
    ...analysis.split(/\n+/).map(paragraph),
    heading('Metric'),
    ...context.metricText.split('\n').map(paragraph),
    heading('Recent errors'),
    ...(context.errorLines.length ? context.errorLines.map((entry) => paragraph(`${entry.message} (trace ${entry.traceId || 'none'})`)) : [paragraph('No errors or warnings in the last 30 minutes.')]),
    ...(context.restartText ? [heading('Restart'), paragraph(context.restartText)] : []),
    heading('Links'),
    link('Grafana panel', context.annotations.dashboard ?? `${$env.GRAFANA_URL}/d/land-plot-overview/land-plot-system`),
    link(`Runbook: ${context.annotations.runbook ?? 'README.md'}`, `${$env.GRAFANA_URL}/d/land-plot-overview/land-plot-system`),
    ...(traceLinks.length ? traceLinks : [link('Jaeger', `${jaeger}/search?service=${context.service}`)]),
  ];

  return {
    json: {
      ...context,
      analysisSource: fromModel ? 'gemini' : 'template',
      issue: {
        fields: {
          project: { key: $env.JIRA_PROJECT_KEY },
          issuetype: { name: 'Bug' },
          summary: `[${context.severity}] ${context.alertname} — ${context.service}`,
          priority: { name: priorities[context.severity] ?? 'Medium' },
          labels: ['incident', `service-${context.service}`, `fp-${context.fingerprint}`],
          description: { type: 'doc', version: 1, content },
        },
      },
    },
  };
});

