return $input.all().map((item, index) => {
  const alert = $('Decide').itemMatching(index).json;
  const restarts = $('Restarts on resolve').itemMatching(index).json;
  const minutes = Math.max(0, (new Date(alert.endsAt) - new Date(alert.startsAt)) / 60000);
  const duration = minutes < 1 ? `${Math.round(minutes * 60)} s` : `${Math.round(minutes * 10) / 10} min`;
  const startedAt = Number(restarts?.data?.result?.[0]?.value?.[1] ?? 0) * 1000;
  const autohealLines = (item.json?.data?.result ?? []).flatMap((stream) => stream.values.map((value) => value[1]));
  let restartText = '';
  if (['ServiceDown', 'ServiceUnhealthy'].includes(alert.alertname)) {
    if (startedAt > Date.parse(alert.startsAt)) {
      restartText = autohealLines.length > 0
        ? `autoheal restarted the container (${autohealLines[0]}); the process started again at ${new Date(startedAt).toISOString()}.`
        : `The process started again at ${new Date(startedAt).toISOString()}, not by autoheal (started by hand or by the Docker restart policy; autoheal only restarts running containers that are unhealthy).`;
    } else {
      restartText = 'The process did not restart: the service recovered without a restart.';
    }
  }
  const text = `Resolved at ${alert.endsAt} after ${duration} (started at ${alert.startsAt}).${restartText ? ' ' + restartText : ''}`;

  return {
    json: {
      ...alert,
      duration,
      comment: { body: { type: 'doc', version: 1, content: [{ type: 'paragraph', content: [{ type: 'text', text }] }] } },
    },
  };
});

return $input.all().map((item, index) => {
  const resolution = $('Resolution').itemMatching(index).json;
  const done = (item.json.transitions ?? []).find((transition) => transition.to?.statusCategory?.key === 'done');

  return { json: { ...resolution, transition: { transition: { id: done?.id ?? '' } } } };
});
